def cand_max_streak_60(close, *_):
    def f(s):
        neg = (s.pct_change() < 0).astype(int).tolist()
        out = []
        n = len(neg)
        for i in range(n):
            w = neg[max(0, i-59): i+1]
            if len(w) < 30:
                out.append(np.nan); continue
            mx = cur = 0
            for v in w:
                cur = cur + 1 if v else 0
                mx = max(mx, cur)
            out.append(-mx)
        return pd.Series(out, index=s.index)
    return per_asset(f)(close)

